import{_ as l,o as e,c as i,ae as r}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"账单退款说明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/zh/guide/10-bill-refund-guide.md","filePath":"v1/zh/guide/10-bill-refund-guide.md"}'),t={name:"v1/zh/guide/10-bill-refund-guide.md"};function o(h,a,d,n,u,s){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="账单退款说明" tabindex="-1">账单退款说明 <a class="header-anchor" href="#账单退款说明" aria-label="Permalink to &quot;账单退款说明&quot;">​</a></h1><h2 id="_1-这是什么功能" tabindex="-1">1. 这是什么功能 <a class="header-anchor" href="#_1-这是什么功能" aria-label="Permalink to &quot;1. 这是什么功能&quot;">​</a></h2><p>“退款”用于记录一笔账单发生退款后的资金变化，并自动抵消统计口径的金额影响。</p><p>系统的做法是：在原账单基础上，新增一笔“金额为负数”的退款记录。</p><ul><li>原账单是支出：退款记录也是“支出”，但金额为负数，用于抵消原支出</li><li>原账单是收入：退款记录也是“收入”，但金额为负数，用于抵消原收入</li></ul><p>同时，退款记录会自动带上“退款”标签，方便后续筛选与核对。</p><h2 id="_2-适用场景" tabindex="-1">2. 适用场景 <a class="header-anchor" href="#_2-适用场景" aria-label="Permalink to &quot;2. 适用场景&quot;">​</a></h2><ul><li>购物退款、退货退款</li><li>账单部分退款（只退一部分金额）</li><li>收入回退（例如打款撤回、收款退回）</li></ul><h2 id="_3-如何使用" tabindex="-1">3. 如何使用 <a class="header-anchor" href="#_3-如何使用" aria-label="Permalink to &quot;3. 如何使用&quot;">​</a></h2><ol><li>进入“账单列表”找到要退款的账单</li><li>对该账单进行左滑操作，选择“退款”</li><li>在退款页面中设置： <ul><li>金额：默认等于原账单金额，可改为部分退款金额</li><li>时间：默认今天，可改为实际退款发生的日期</li><li>标签：默认继承原账单的标签，并自动追加“退款”标签</li><li>备注：可选，用于补充说明</li></ul></li><li>点击“确定/完成”保存</li></ol><p>保存后，列表会新增一笔退款记录，用于抵消对应的金额影响。</p><h2 id="_4-使用规则与注意事项" tabindex="-1">4. 使用规则与注意事项 <a class="header-anchor" href="#_4-使用规则与注意事项" aria-label="Permalink to &quot;4. 使用规则与注意事项&quot;">​</a></h2><ul><li>退款金额建议填写“实际退回的金额”，不需要手动加负号。</li><li>支出退款与收入退款都会按“负数金额”的方式记录，因此在统计中会自动抵消。</li><li>支持多次退款：同一笔账单如果分多次退款，可以重复操作多次，每次生成一笔退款记录。</li><li>如果您删除了退款记录，对应的抵消效果也会消失（统计会回到未退款状态）。</li></ul><h2 id="_5-常见问题" tabindex="-1">5. 常见问题 <a class="header-anchor" href="#_5-常见问题" aria-label="Permalink to &quot;5. 常见问题&quot;">​</a></h2><h3 id="q1-部分退款怎么记" tabindex="-1">Q1：部分退款怎么记？ <a class="header-anchor" href="#q1-部分退款怎么记" aria-label="Permalink to &quot;Q1：部分退款怎么记？&quot;">​</a></h3><p>在退款页面把金额改为实际退款金额即可。您也可以多次退款，每次填各自的退款金额。</p><h3 id="q2-退款会影响原账单吗" tabindex="-1">Q2：退款会影响原账单吗？ <a class="header-anchor" href="#q2-退款会影响原账单吗" aria-label="Permalink to &quot;Q2：退款会影响原账单吗？&quot;">​</a></h3><p>原账单本身不会被修改金额；退款是以“新增一笔退款记录”的方式实现的。这样可以保留原始消费记录，同时让统计结果可解释、可追溯。</p><h3 id="q3-怎么快速找到所有退款" tabindex="-1">Q3：怎么快速找到所有退款？ <a class="header-anchor" href="#q3-怎么快速找到所有退款" aria-label="Permalink to &quot;Q3：怎么快速找到所有退款？&quot;">​</a></h3><p>退款记录会自动带“退款”标签，您可以在筛选/搜索中按标签筛选查看。</p>',20)])])}const p=l(t,[["render",o]]);export{c as __pageData,p as default};
